WITH filtered AS (SELECT id, store_id, product_id, sale_date, units, revenue, ROUND(revenue, 1) AS revenue_rounded, ROUND(revenue, 1) AS revenue_rounded_2 FROM store_sales WHERE MONTH(sale_date) IN (1, 5, 6)) SELECT * FROM (SELECT id, product_id, revenue_rounded_2, revenue, revenue_rounded FROM filtered) src UNPIVOT INCLUDE NULLS (value FOR measure IN (revenue_rounded_2, revenue, revenue_rounded));
